--
-- 0001 users (up): user accounts.
--
-- Conventions for all migrations (see docs/ARCHITECTURE.md, "Data model"):
-- * Primary keys are UUIDv7 values generated by the API, never by the database.
-- * updated_at is maintained by the application.
-- * Accounts are never hard-deleted. Account deletion scrubs personal data and sets
--   deleted_at, so foreign keys from content, moderation and audit rows stay valid.

BEGIN;

CREATE TABLE users (
    id                   uuid        PRIMARY KEY,
    email                text,
    password_hash        text,
    display_name         text,
    locale               text        NOT NULL DEFAULT 'hu',
    is_global_admin      boolean     NOT NULL DEFAULT false,
    notify_comments      boolean     NOT NULL DEFAULT true,
    notify_announcements boolean     NOT NULL DEFAULT true,
    password_changed_at  timestamptz,
    last_login_at        timestamptz,
    created_at           timestamptz NOT NULL DEFAULT now(),
    updated_at           timestamptz NOT NULL DEFAULT now(),
    deleted_at           timestamptz,

    CONSTRAINT users_locale_check
        CHECK (locale IN ('hu', 'en')),
    CONSTRAINT users_email_check
        CHECK (email IS NULL OR (char_length(email) BETWEEN 3 AND 254 AND position('@' IN email) > 1)),
    CONSTRAINT users_display_name_check
        CHECK (display_name IS NULL OR char_length(display_name) BETWEEN 2 AND 40),
    -- Only Argon2id PHC strings are accepted, never plaintext.
    CONSTRAINT users_password_hash_check
        CHECK (password_hash IS NULL OR password_hash LIKE '$argon2id$%'),
    -- An active account has all login fields.
    CONSTRAINT users_active_fields_check
        CHECK (deleted_at IS NOT NULL OR (email IS NOT NULL AND password_hash IS NOT NULL AND display_name IS NOT NULL)),
    -- A deleted account keeps no personal data and no privileges.
    CONSTRAINT users_deleted_scrubbed_check
        CHECK (deleted_at IS NULL OR (email IS NULL AND password_hash IS NULL AND display_name IS NULL AND NOT is_global_admin))
);

-- One account per e-mail address, case-insensitive. Deleted accounts have email = NULL.
CREATE UNIQUE INDEX users_email_key ON users (lower(email)) WHERE email IS NOT NULL;
-- Global administration user list (newest first, cursor pagination).
CREATE INDEX users_created_at_idx ON users (created_at DESC, id DESC);

COMMIT;
